const crypto = require('crypto');
const item = items[0].json;
const sigHeader = item.headers?.['x-webwelle-signature'] || item.headers?.['X-Webwelle-Signature'];
const secret = item._webwelleN8nWebhookSecret || 'dev-n8n-secret';
let raw = typeof item.rawBody === 'string' ? item.rawBody : '';
if (!raw && item.body !== undefined) {
  raw = typeof item.body === 'string' ? item.body : JSON.stringify(item.body);
}
if (!raw) raw = '{}';
const candidateStrings = new Set([raw]);
if (item.body && typeof item.body === 'object') {
  candidateStrings.add(JSON.stringify(item.body));
  const keys = Object.keys(item.body).sort();
  const sorted = {};
  for (const k of keys) sorted[k] = item.body[k];
  candidateStrings.add(JSON.stringify(sorted));
}
let verified = false;
let expectedHex = '';
for (const s of candidateStrings) {
  expectedHex = crypto.createHmac('sha256', secret).update(s).digest('hex');
  if (sigHeader && sigHeader === expectedHex) {
    verified = true;
    break;
  }
}
if (!verified) {
  throw new Error('Ungueltige oder fehlende x-webwelle-signature');
}
let body;
try {
  body = JSON.parse(raw);
} catch {
  body = item.body && typeof item.body === 'object' ? item.body : {};
}
const leadId = body.leadId || '';
const token = body.token || '';
const industry = (body.industry || 'Dienstleister').trim();
const postalCode = (body.postalCode || '').trim();
const market = (body.market || 'DE').trim();
const callbackBaseUrl = String(body.callbackBaseUrl || '').replace(/\/$/, '');
if (!leadId) throw new Error('leadId fehlt');
if (!postalCode) throw new Error('postalCode fehlt');
return [{ json: { leadId, token, industry, postalCode, market, callbackBaseUrl } }];

const lead = $('Normalize And Verify HMAC').first().json;
const geo = items[0].json;
const results = geo.results || [];
if (!results.length) {
  return [{
    json: {
      ...lead,
      lat: null,
      lng: null,
      locality: '',
      formattedAddress: '',
      geocodeError: 'empty',
    },
  }];
}
const loc = results[0].geometry?.location || {};
const comps = results[0].address_components || [];
const locality =
  (comps.find((c) => c.types?.includes('locality')) || {}).long_name ||
  (comps.find((c) => c.types?.includes('postal_town')) || {}).long_name ||
  (comps.find((c) => c.types?.includes('sublocality')) || {}).long_name ||
  '';
return [{
  json: {
    ...lead,
    lat: loc.lat,
    lng: loc.lng,
    locality,
    formattedAddress: results[0].formatted_address || '',
  },
}];

/**
 * n8n Code-Node: Ersatz fuer HTTP „Places Text Search“.
 * Reihenfolge: Places API (New) → Places API (Legacy + Details) → CSE (nur wenn Engine Web-Suche erlaubt).
 */
const pg = items[0].json;
const inj = $('Inject Webwelle Env').first().json;
const httpRequest = this.helpers.httpRequest.bind(this.helpers);
const mapsKey = inj._googleMapsApiKey || '';
const cseKey = inj._googleCseApiKey || '';
const cseId = inj._googleCseId || '';

const textQuery = `${pg.industry || ''} ${pg.postalCode || ''} ${pg.locality || ''}`.trim();
const locationBias =
  pg.lat != null && pg.lng != null
    ? { circle: { center: { latitude: pg.lat, longitude: pg.lng }, radius: 20000 } }
    : undefined;

let places = [];
let discoverSource = 'none';

/** Places API (New) — benoetigt „Places API (New)“ in GCP */
if (mapsKey && textQuery && !places.length) {
  try {
    const body = { textQuery };
    if (locationBias) body.locationBias = locationBias;
    const res = await httpRequest({
      method: 'POST',
      url: 'https://places.googleapis.com/v1/places:searchText',
      headers: {
        'X-Goog-Api-Key': mapsKey,
        'X-Goog-FieldMask':
          'places.displayName,places.formattedAddress,places.websiteUri,places.googleMapsUri,places.location',
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
      timeout: 20000,
      json: true,
      ignoreResponseCode: true,
    });
    if (res && Array.isArray(res.places) && res.places.length) {
      places = res.places;
      discoverSource = 'places_new';
    }
  } catch {
    /* weiter */
  }
}

/** Places API (Legacy) Text Search + Details — benoetigt „Places API“ (klassisch) in GCP */
if (mapsKey && textQuery && !places.length) {
  try {
    let url =
      'https://maps.googleapis.com/maps/api/place/textsearch/json?query=' +
      encodeURIComponent(textQuery) +
      '&key=' +
      encodeURIComponent(mapsKey);
    if (pg.lat != null && pg.lng != null) {
      url += '&location=' + encodeURIComponent(`${pg.lat},${pg.lng}`) + '&radius=20000';
    }
    const data = await httpRequest({ method: 'GET', url, timeout: 20000, json: true, ignoreResponseCode: true });
    const status = data?.status || '';
    if (status === 'OK' || status === 'ZERO_RESULTS') {
      const legacyPlaces = [];
      for (const r of (data.results || []).slice(0, 10)) {
        if (!r.place_id) continue;
        let website = '';
        let mapsUrl = '';
        let formatted = r.formatted_address || '';
        try {
          const detUrl =
            'https://maps.googleapis.com/maps/api/place/details/json?place_id=' +
            encodeURIComponent(r.place_id) +
            '&fields=name,website,formatted_address,url&key=' +
            encodeURIComponent(mapsKey);
          const det = await httpRequest({ method: 'GET', url: detUrl, timeout: 12000, json: true, ignoreResponseCode: true });
          if (det?.status === 'OK' && det.result) {
            website = det.result.website || '';
            mapsUrl = det.result.url || '';
            formatted = det.result.formatted_address || formatted;
          }
        } catch {
          /* skip details */
        }
        if (!website) continue;
        legacyPlaces.push({
          displayName: { text: r.name || '' },
          formattedAddress: formatted,
          websiteUri: website,
          googleMapsUri: mapsUrl,
        });
      }
      if (legacyPlaces.length) {
        places = legacyPlaces;
        discoverSource = 'places_legacy';
      }
    }
  } catch {
    /* weiter */
  }
}

/** CSE — nur sinnvoll bei Engine mit echter Web-Suche (neue Engines oft nur bis 50 Domains) */
if (!places.length && cseKey && cseId && textQuery) {
  const country =
    pg.market === 'CH' ? 'Schweiz' : pg.market === 'AT' ? 'Oesterreich' : 'Deutschland';
  const q = `${pg.industry} ${pg.postalCode} ${pg.locality || ''} ${country}`.trim();
  try {
    const url =
      'https://www.googleapis.com/customsearch/v1?key=' +
      encodeURIComponent(cseKey) +
      '&cx=' +
      encodeURIComponent(cseId) +
      '&q=' +
      encodeURIComponent(q) +
      '&num=10';
    const cse = await httpRequest({ method: 'GET', url, timeout: 15000, json: true, ignoreResponseCode: true });
    const itemsList = cse?.items || [];
    places = itemsList
      .map((it) => {
        const link = it.link || '';
        if (!link || !/^https?:\/\//i.test(link)) return null;
        const title = (it.title || '').replace(/\s*[-|–|—].*$/, '').trim().slice(0, 200);
        return {
          displayName: { text: title || link },
          formattedAddress: pg.formattedAddress || String(pg.postalCode || ''),
          websiteUri: link,
          googleMapsUri: '',
        };
      })
      .filter(Boolean);
    if (places.length) discoverSource = 'cse';
  } catch {
    /* leer */
  }
}

return [{ json: { places, discoverSource } }];

/**
 * n8n Code-Node: Places/CSE-Rohdaten → deduplizierte Wettbewerber-Liste.
 * Robust gegen fehlendes URL-Global (Task-Runner), mehrere Input-Items und Feldvarianten.
 */
const pg = $('Parse Geocode').first().json;
const placesRes = items[0]?.json || {};

function asPlaceList(source, allItems) {
  if (Array.isArray(source.places) && source.places.length) return source.places;
  if (allItems.length > 1) {
    return allItems
      .map((it) => it.json)
      .filter((j) => j && (j.websiteUri || j.website || j.displayName || j.formattedAddress));
  }
  if (source.websiteUri || source.website || source.displayName || source.formattedAddress) {
    return [source];
  }
  return [];
}

const places = asPlaceList(placesRes, items);
const discoverSource = placesRes.discoverSource || 'none';

function websiteOf(p) {
  const raw = p.websiteUri ?? p.website ?? p.url ?? '';
  if (typeof raw === 'string') return raw.trim();
  if (raw && typeof raw === 'object') {
    if (typeof raw.uri === 'string') return raw.uri.trim();
    if (typeof raw.value === 'string') return raw.value.trim();
  }
  return '';
}

function nameOf(p) {
  const dn = p.displayName;
  if (dn && typeof dn === 'object' && typeof dn.text === 'string') return dn.text;
  if (typeof dn === 'string') return dn;
  return p.name || p.title || '';
}

function domainFromUrl(u) {
  const s = String(u || '').trim();
  if (!s) return '';
  try {
    if (typeof URL !== 'undefined') {
      const url = /^https?:\/\//i.test(s) ? s : `https://${s}`;
      return new URL(url).hostname.replace(/^www\./i, '').toLowerCase();
    }
  } catch {
    /* regex fallback */
  }
  const m =
    s.match(/^https?:\/\/([^/?#]+)/i) ||
    s.match(/^www\.([^/?#]+)/i) ||
    s.match(/^([a-z0-9][-a-z0-9]*(?:\.[a-z0-9][-a-z0-9]*)+)/i);
  if (!m) return '';
  return m[1].replace(/^www\./i, '').toLowerCase();
}

function normalizeUrl(u) {
  const s = String(u || '').trim();
  if (!s) return '';
  try {
    if (typeof URL !== 'undefined') {
      const url = /^https?:\/\//i.test(s) ? s : `https://${s}`;
      const parsed = new URL(url);
      const path = parsed.pathname.replace(/\/$/, '');
      return parsed.origin + path || url;
    }
  } catch {
    /* fall through */
  }
  return /^https?:\/\//i.test(s) ? s : `https://${s}`;
}

function isBlockedDomain(dom) {
  const d = dom.toLowerCase();
  return /(^|\.)google\.|(^|\.)gstatic\.|(^|\.)facebook\.|(^|\.)fbcdn\.|(^|\.)instagram\.|(^|\.)linkedin\.|(^|\.)youtube\.|(^|\.)youtu\.be$|gelbeseiten|11880|dasoertliche|kennst-du-einen|(^|\.)wikipedia\.|(^|\.)amazon\.|(^|\.)ebay\.|(^|\.)yelp\./i.test(
    d,
  );
}

const competitors = [];
for (const p of places) {
  const w = websiteOf(p);
  if (!w) continue;
  const dom = domainFromUrl(w);
  if (!dom || isBlockedDomain(dom)) continue;
  const name = nameOf(p) || dom;
  competitors.push({
    name: String(name).slice(0, 200),
    domain: dom,
    websiteUrl: normalizeUrl(w),
    mapsUri: p.googleMapsUri || p.url || '',
    address: p.formattedAddress || '',
  });
}

const cseUsed = discoverSource === 'cse';

const uniq = [];
const seen = new Set();
for (const c of competitors) {
  if (seen.has(c.domain)) continue;
  seen.add(c.domain);
  uniq.push(c);
}
const top = uniq.slice(0, 10);

return [
  {
    json: {
      leadId: pg.leadId,
      token: pg.token,
      industry: pg.industry,
      postalCode: pg.postalCode,
      market: pg.market,
      locality: pg.locality,
      lat: pg.lat,
      lng: pg.lng,
      formattedAddress: pg.formattedAddress,
      competitors: top,
      discoverMeta: {
        placesCount: places.length,
        cseUsed,
        picked: top.length,
        source: discoverSource,
      },
    },
  },
];

/** OpenRouter chat/completions mit Modell-Fallback (404 = Modell nicht verfügbar). */
function openRouterModels(preferred) {
  const list = [
    preferred,
    'google/gemini-2.0-flash-001',
    'meta-llama/llama-3.1-8b-instruct:free',
    'openai/gpt-4o-mini',
  ].filter(Boolean);
  const seen = new Set();
  return list.filter((m) => {
    if (seen.has(m)) return false;
    seen.add(m);
    return true;
  });
}

async function openRouterChat(httpRequest, opts) {
  const { apiKey, referer, title, body, formatErr } = opts;
  if (!apiKey) {
    throw new Error('OPENROUTER_API_KEY fehlt in n8n (Container-Env setzen).');
  }
  const models = openRouterModels(body.model);
  let lastErr = null;
  for (const model of models) {
    try {
      const res = await httpRequest({
        method: 'POST',
        url: 'https://openrouter.ai/api/v1/chat/completions',
        headers: {
          Authorization: 'Bearer ' + apiKey,
          'HTTP-Referer': referer,
          'X-Title': title,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ ...body, model }),
        timeout: opts.timeout || 45000,
        json: true,
        ignoreResponseCode: true,
      });
      if (res && res.error) {
        const code = res.error.code || res.status;
        const msg = res.error.message || JSON.stringify(res.error);
        if (code === 404 || /404|not found|no endpoints/i.test(String(msg))) {
          lastErr = new Error(msg);
          continue;
        }
        throw new Error(msg);
      }
      if (res?.choices?.length) return res;
      lastErr = new Error('Leere OpenRouter-Antwort');
    } catch (e) {
      lastErr = e;
      const msg = formatErr(e);
      if (/404|not found|no endpoints/i.test(msg)) continue;
      throw e;
    }
  }
  throw lastErr || new Error('Kein OpenRouter-Modell verfügbar (alle Fallbacks fehlgeschlagen).');
}

function formatErr(e) {
  if (e == null) return "Unbekannter Fehler";
  if (typeof e === "string") return e;
  if (e instanceof Error) return e.message || "Unbekannter Fehler";
  if (typeof e === "object") {
    const o = e;
    if (typeof o.message === "string" && o.message) return o.message;
    if (typeof o.error === "string" && o.error) return o.error;
    try {
      const s = JSON.stringify(e);
      if (s && s !== "{}") return s.slice(0, 200);
    } catch {
      /* ignore */
    }
  }
  return String(e);
}

const row = items[0].json;
const list = (row.competitors || []).slice(0, 8);
const httpRequest = this.helpers.httpRequest.bind(this.helpers);
const inj = $('Inject Webwelle Env').first().json;
const key = inj._openrouterApiKey || '';
const model = inj._openrouterModel || 'google/gemini-2.0-flash-001';
const referer = inj._webwelleAppBaseUrl || inj._nextPublicAppUrl || 'https://webpfad.de';

const STOP = new Set([
  'nbsp', 'auml', 'ouml', 'uuml', 'euml', 'quot', 'amp', 'reg', 'copy', 'thinsp',
  'ihre', 'ihnen', 'unsere', 'unser', 'oder', 'sind', 'wird', 'werden', 'mehr', 'erfahren',
  'home', 'button', 'click', 'here', 'some', 'work', 'site', 'under', 'construction', 'sorry',
  'thank', 'being', 'doing', 'this', 'that', 'with', 'from', 'have', 'been', 'were', 'your',
  'kontakt', 'impressum', 'datenschutz', 'agb', 'cookie', 'cookies', 'menu', 'navigation',
  'weiterlesen', 'lesen', 'alle', 'auch', 'nicht', 'eine', 'einer', 'eines', 'über', 'beim',
]);

function decodeHtmlEntities(raw) {
  if (!raw || typeof raw !== 'string') return '';
  return raw
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&auml;/gi, 'ä')
    .replace(/&ouml;/gi, 'ö')
    .replace(/&uuml;/gi, 'ü')
    .replace(/&Auml;/gi, 'Ä')
    .replace(/&Ouml;/gi, 'Ö')
    .replace(/&Uuml;/gi, 'Ü')
    .replace(/&szlig;/gi, 'ß')
    .replace(/&quot;/gi, '"')
    .replace(/&#[0-9]+;/g, ' ')
    .replace(/&[a-z]+;/gi, ' ');
}

function extractText(html) {
  if (!html || typeof html !== 'string') return '';
  const decoded = decodeHtmlEntities(html);
  return decoded
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 8000);
}

function tokenize(text) {
  return text
    .toLowerCase()
    .replace(/[^a-zäöüß0-9\s-]/g, ' ')
    .split(/\s+/)
    .filter((w) => w.length >= 4 && w.length < 22 && !STOP.has(w) && !/^\d+$/.test(w) && !/^[a-z]{1,2}$/.test(w));
}

function topWords(text, limit) {
  const words = tokenize(text);
  const freq = {};
  for (const w of words) freq[w] = (freq[w] || 0) + 1;
  return Object.entries(freq)
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit)
    .map(([w]) => w);
}

function aggregateUsedKeywords(perSite) {
  const freq = {};
  for (const s of perSite) {
    for (const w of s.usedKeywords || []) {
      if (!w || STOP.has(w)) continue;
      freq[w] = (freq[w] || 0) + 1;
    }
  }
  return Object.entries(freq)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 40)
    .map(([phrase, count]) => ({ phrase, count }));
}

function synthesizeKeywords(perSite, leadRow) {
  const freq = {};
  for (const s of perSite) {
    for (const w of s.usedKeywords || []) {
      if (!w || STOP.has(w)) continue;
      freq[w] = (freq[w] || 0) + 1;
    }
  }
  const industry = String(leadRow.industry || '').trim();
  const locality = String(leadRow.locality || '').trim();
  const plz = String(leadRow.postalCode || '').trim();
  const location = locality || (plz ? `PLZ ${plz}` : '');

  const keywords = [];
  if (industry && location) {
    keywords.push({
      keyword: `${industry} ${location}`,
      volume: null,
      cpc: null,
      competition: null,
      intent: 'commercial',
      cluster: 'lokal',
    });
  }
  if (industry) {
    keywords.push({
      keyword: `${industry} in der Nähe`,
      volume: null,
      cpc: null,
      competition: null,
      intent: 'commercial',
      cluster: 'lokal',
    });
  }

  for (const [term, count] of Object.entries(freq).sort((a, b) => b[1] - a[1]).slice(0, 18)) {
    const kw =
      industry && !term.includes(industry.toLowerCase().slice(0, 4))
        ? `${term} ${industry}`.trim()
        : term;
    keywords.push({
      keyword: kw.slice(0, 80),
      volume: null,
      cpc: null,
      competition: count >= 3 ? 'medium' : 'low',
      intent: 'informational',
      cluster: location || 'wettbewerb',
    });
  }

  const seen = new Set();
  return keywords.filter((k) => {
    const n = k.keyword.toLowerCase();
    if (seen.has(n)) return false;
    seen.add(n);
    return true;
  });
}

const perSite = [];
for (const c of list) {
  let html = '';
  try {
    html = await httpRequest({
      method: 'GET',
      url: c.websiteUrl,
      timeout: 7000,
      headers: { 'User-Agent': 'WebwelleResearch/1.0', Accept: 'text/html' },
      json: false,
    });
    if (typeof html !== 'string') html = JSON.stringify(html);
  } catch {
    html = '';
  }
  const t = extractText(html);
  perSite.push({ domain: c.domain, usedKeywords: topWords(t, 12) });
}

const user = JSON.stringify(
  {
    branche: row.industry,
    plz: row.postalCode,
    ort: row.locality,
    markt: row.market,
    konkurrentenDomains: list.map((x) => x.domain),
    textAusschnitte: perSite,
    hinweis:
      'Nutze nur sinnvolle lokale SEO-Begriffe (Handwerk/Branche/Ort). Ignoriere HTML-Artefakte und Stopwords.',
  },
  null,
  2,
);

const openRouterBody = {
  model,
  temperature: 0.35,
  stream: false,
  messages: [
    {
      role: 'system',
      content:
        'Du bist Senior SEO fuer lokale DACH-KMU. Antworte NUR mit JSON ohne Markdown: {keywords:[{keyword,volume,cpc,competition,intent,cluster}],usedKeywords:[{phrase,count}],gaps:string[],perSite:[{domain,usedKeywords:string[]}],provider:"crawl_llm",partial:false,done:true}',
    },
    { role: 'user', content: user },
  ],
};

let parsed = {
  keywords: synthesizeKeywords(perSite, row),
  usedKeywords: aggregateUsedKeywords(perSite),
  gaps: [],
  perSite,
  provider: 'crawl_llm',
  partial: false,
  done: true,
};

try {
  const or = await openRouterChat(httpRequest, {
    apiKey: key,
    referer,
    title: 'Webwelle seo-keywords-v2',
    body: openRouterBody,
    formatErr,
    timeout: 35000,
  });
  const text = or.choices?.[0]?.message?.content || '';
  const fence = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = fence ? fence[1].trim() : text.trim();
  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start >= 0 && end > start) {
    const j = JSON.parse(candidate.slice(start, end + 1));
    const llmKeywords = Array.isArray(j.keywords) ? j.keywords.filter((k) => k && k.keyword) : [];
    parsed = {
      keywords: llmKeywords.length ? llmKeywords : parsed.keywords,
      usedKeywords: Array.isArray(j.usedKeywords) && j.usedKeywords.length ? j.usedKeywords : parsed.usedKeywords,
      gaps: Array.isArray(j.gaps) ? j.gaps : [],
      perSite: Array.isArray(j.perSite) && j.perSite.length ? j.perSite : perSite,
      provider: 'crawl_llm',
      partial: false,
      done: true,
    };
  }
} catch (e) {
  parsed.gaps = [
    "KI-Keyword-Analyse nicht verfügbar (" +
      formatErr(e) +
      "). Es werden Fallback-Begriffe aus dem Wettbewerber-Crawl genutzt.",
  ];
  parsed.partial = true;
}

if (!parsed.keywords.length) {
  parsed.keywords = synthesizeKeywords(parsed.perSite.length ? parsed.perSite : perSite, row);
}
if (!parsed.usedKeywords.length) {
  parsed.usedKeywords = aggregateUsedKeywords(parsed.perSite.length ? parsed.perSite : perSite);
}

return [{ json: { leadId: row.leadId, token: row.token, ...parsed } }];

const crypto = require('crypto');
const row = items[0].json;
const inj = $('Inject Webwelle Env').first().json;
const secret = inj._webwelleN8nWebhookSecret || 'dev-n8n-secret';
const normalizedInput = $('Normalize And Verify HMAC').first().json;
const base = ((row.callbackBaseUrl || normalizedInput.callbackBaseUrl || inj._webwelleAppBaseUrl || inj._nextPublicAppUrl) || '').replace(/\/$/, '');
if (!base) throw new Error('WEBWELLE_APP_BASE_URL fehlt');
const callbackUrl = base + '/api/n8n/seo-keywords';
const bodyObj = {
  leadId: row.leadId,
  token: row.token || normalizedInput.token || '',
  keywords: row.keywords || [],
  provider: row.provider || 'crawl_llm',
  done: row.done !== false,
